// TODO: progenitor only supports OpenAPI 3.0, so the xtask downgrades the
// crates.io OpenAPI 3.1 spec before generating this client. Once progenitor
// supports 3.1 (https://github.com/oxidecomputer/progenitor/issues/762),
// generate from the upstream spec directly and remove `downgrade_to_openapi_3_0`
// from `tooling/xtask/src/tasks/gpui/crates_io_client.rs`.

//! A client for the subset of the [crates.io API](https://crates.io/data-access#api)
//! that Zed's tooling needs.
//!
//! The client is generated by progenitor from `openapi.json`, a filtered copy
//! of the crates.io OpenAPI spec. To support another endpoint, add it to
//! `SUPPORTED_ENDPOINTS` in `tooling/xtask/src/tasks/gpui/crates_io_client.rs`
//! and run `cargo xtask gpui update-crates-io-client`.

#[allow(clippy::all, reason = "generated code")]
mod generated {
    progenitor::generate_api!(
        spec = "openapi.json",
        inner_type = crate::ClientState,
        pre_hook_async = crate::pre_request_hook,
    );
}

use std::convert::Infallible;
use std::sync::Arc;
use std::time::Duration;

use anyhow::{Context as _, Result, bail};
use reqwest::header::{HeaderValue, USER_AGENT};
use tokio::sync::Mutex;
use tokio::time::Instant;

pub use generated::*;

pub const CRATES_IO_BASE_URL: &str = "https://crates.io";

/// The crates.io data access policy allows at most one request per second.
const MIN_REQUEST_INTERVAL: Duration = Duration::from_secs(1);

/// State shared by all clones of a [`Client`], used to comply with the
/// [crates.io data access policy](https://crates.io/data-access#api).
#[derive(Clone, Debug)]
pub struct ClientState {
    user_agent: HeaderValue,
    last_request_started_at: Arc<Mutex<Option<Instant>>>,
}

impl ClientState {
    /// `user_agent` must identify the application and should include a way
    /// for the crates.io team to get in touch, such as a repository URL.
    pub fn new(user_agent: &str) -> Result<Self> {
        if user_agent.trim().is_empty() {
            bail!("crates.io requires a user agent that identifies the application");
        }
        let user_agent = HeaderValue::from_str(user_agent)
            .with_context(|| format!("invalid user agent {user_agent:?}"))?;
        Ok(Self {
            user_agent,
            last_request_started_at: Arc::new(Mutex::new(None)),
        })
    }
}

impl Client {
    pub fn for_crates_io(user_agent: &str) -> Result<Self> {
        Ok(Self::new(CRATES_IO_BASE_URL, ClientState::new(user_agent)?))
    }
}

async fn pre_request_hook(
    state: &ClientState,
    request: &mut reqwest::Request,
) -> Result<(), Infallible> {
    request
        .headers_mut()
        .insert(USER_AGENT, state.user_agent.clone());

    // Holding the lock while sleeping queues up concurrent requests so that
    // they are sent one at a time.
    let mut last_request_started_at = state.last_request_started_at.lock().await;
    if let Some(last_request_started_at) = *last_request_started_at {
        tokio::time::sleep_until(last_request_started_at + MIN_REQUEST_INTERVAL).await;
    }
    *last_request_started_at = Some(Instant::now());
    Ok(())
}
